body.query:
	*[_type == 'newsOverviewCategory'][0] {
		...,
		content {
			contactPersonsSection {
				...,
				contactPersons[]-> {

  firstName,
  lastName,
  phone,
  image,
  contactAs,
  "email": affiliations[0].role->email,
  "role": affiliations[0].role->title,
  "taskDescription": affiliations[0].taskDescription,

				}
			}
		}
	}
